-- BEGIN manual SQL: prisma/sql/pre_neon/02c_seasons_enrollments.sql
-- Swim Flow / Etapa 02C: manual PostgreSQL constraints.
-- This file is an INPUT for the first versioned Neon baseline migration.
-- DO NOT execute against a deployed database or the legacy Supabase schema.
-- Prisma 6 does not represent partial unique indexes or CHECK constraints.

ALTER TABLE "seasons"
  ADD CONSTRAINT "seasons_year_range_chk"
  CHECK ("year" BETWEEN 2000 AND 2100),
  ADD CONSTRAINT "seasons_date_order_chk"
  CHECK ("starts_on" <= "ends_on");

-- At most one ACTIVE season. Other planned/closed seasons are unrestricted.
CREATE UNIQUE INDEX "seasons_one_active_idx"
  ON "seasons" ("status") WHERE "status" = 'ACTIVE';

ALTER TABLE "student_classes"
  ADD CONSTRAINT "student_classes_date_order_chk"
  CHECK ("to_date" IS NULL OR "from_date" <= "to_date");

-- A student may join more than one class only when records are non-primary.
-- A primary registration is unique among CURRENT (to_date IS NULL) links.
CREATE UNIQUE INDEX "student_classes_one_active_primary_idx"
  ON "student_classes" ("student_id")
  WHERE "to_date" IS NULL AND "is_primary" = TRUE;

-- No two concurrently active links between the same student and class.
-- Historical re-enrolments in the SAME class remain possible.
CREATE UNIQUE INDEX "student_classes_one_active_pair_idx"
  ON "student_classes" ("student_id", "class_id")
  WHERE "to_date" IS NULL;

-- Multiple assistant coaches are allowed, only one head coach per class.
CREATE UNIQUE INDEX "class_teachers_one_head_coach_idx"
  ON "class_teachers" ("class_id")
  WHERE "role" = 'head_coach';

-- Age bands may intentionally remain NULL when the category has no bound.
ALTER TABLE "categories"
  ADD CONSTRAINT "categories_age_range_chk"
  CHECK (
    ("age_min" IS NULL OR "age_min" >= 0)
    AND ("age_max" IS NULL OR "age_max" >= 0)
    AND ("age_min" IS NULL OR "age_max" IS NULL OR "age_min" <= "age_max")
  );
-- END manual SQL: prisma/sql/pre_neon/02c_seasons_enrollments.sql

-- BEGIN manual SQL: prisma/sql/pre_neon/02c2_guardians_identity.sql
-- Include in the FIRST versioned Neon migration, AFTER Prisma's model SQL.
-- Not applied to any database by this PR. PostgreSQL accepts many false values,
-- but only one primary guardian per student.
CREATE UNIQUE INDEX "student_guardians_one_primary_idx"
  ON "student_guardians" ("student_id")
  WHERE "is_primary" = TRUE;

-- More than one teacher cannot claim the same auth account because
-- Teacher.profileId has a Prisma @unique, enforced by a database UNIQUE index.
-- Link accounts only via authenticated ADMIN workflows with verified identity.
-- Never infer a teacher's account by display name or matching email.
-- END manual SQL: prisma/sql/pre_neon/02c2_guardians_identity.sql

-- BEGIN manual SQL: prisma/sql/pre_neon/02c3_departure_history.sql
-- Append to the initial Prisma-generated Neon baseline, after the tables exist.
-- This SQL has NOT been executed against any database.
-- Guarantees at most one currently active departure per student while
-- permitting multiple historical departures after a genuine return.
CREATE UNIQUE INDEX "ex_students_one_current_departure_idx"
  ON "ex_students" ("student_id")
  WHERE "reactivated_at" IS NULL AND "voided_at" IS NULL;

ALTER TABLE "ex_students"
  ADD CONSTRAINT "ex_students_single_closure_chk"
    CHECK ("reactivated_at" IS NULL OR "voided_at" IS NULL),
  ADD CONSTRAINT "ex_students_nonnegative_achievements_chk"
    CHECK ("achievements" >= 0);
-- END manual SQL: prisma/sql/pre_neon/02c3_departure_history.sql

-- BEGIN manual SQL: prisma/sql/pre_neon/02d_domain_invariants.sql
-- Additional immutable PostgreSQL domain checks on a FRESH schema.
-- Run after the Prisma-generated CREATE TABLE / CREATE TYPE statements.

ALTER TABLE "pool_results"
  ADD CONSTRAINT "pool_results_distance_positive_chk" CHECK ("distance_meters" > 0),
  ADD CONSTRAINT "pool_results_pool_length_positive_chk" CHECK ("pool_length_meters" IS NULL OR "pool_length_meters" > 0),
  ADD CONSTRAINT "pool_results_duration_positive_chk" CHECK ("duration_ms" IS NULL OR "duration_ms" > 0),
  ADD CONSTRAINT "pool_results_position_positive_chk" CHECK ("position" IS NULL OR "position" > 0),
  ADD CONSTRAINT "pool_results_classified_duration_chk" CHECK ("status" <> 'CLASSIFIED' OR "duration_ms" IS NOT NULL);

ALTER TABLE "open_water_results"
  ADD CONSTRAINT "open_water_results_distance_positive_chk" CHECK ("distance_meters" > 0),
  ADD CONSTRAINT "open_water_results_duration_positive_chk" CHECK ("duration_ms" IS NULL OR "duration_ms" > 0),
  ADD CONSTRAINT "open_water_results_position_positive_chk" CHECK ("position" IS NULL OR "position" > 0),
  ADD CONSTRAINT "open_water_results_classified_duration_chk" CHECK ("status" <> 'CLASSIFIED' OR "duration_ms" IS NOT NULL);

ALTER TABLE "pools"
  ADD CONSTRAINT "pools_length_positive_chk" CHECK ("length_meters" > 0),
  ADD CONSTRAINT "pools_capacity_positive_chk" CHECK ("max_capacity" IS NULL OR "max_capacity" > 0);

ALTER TABLE "technical_assessment_criteria"
  ADD CONSTRAINT "technical_criteria_score_bounds_chk" CHECK ("min_score" >= 0 AND "max_score" >= "min_score");

ALTER TABLE "technical_assessment_scores"
  ADD CONSTRAINT "technical_scores_nonnegative_chk" CHECK ("score" IS NULL OR "score" >= 0);

ALTER TABLE "anthropometric_assessments"
  ADD CONSTRAINT "anthropometry_positive_measures_chk"
  CHECK (
    ("height_cm" IS NULL OR "height_cm" > 0) AND
    ("body_mass_kg" IS NULL OR "body_mass_kg" > 0) AND
    ("arm_span_cm" IS NULL OR "arm_span_cm" > 0) AND
    ("leg_length_cm" IS NULL OR "leg_length_cm" > 0) AND
    ("foot_length_cm" IS NULL OR "foot_length_cm" > 0) AND
    ("hand_length_cm" IS NULL OR "hand_length_cm" > 0) AND
    ("trunk_length_cm" IS NULL OR "trunk_length_cm" > 0)
  );
-- END manual SQL: prisma/sql/pre_neon/02d_domain_invariants.sql
